import {
  Container,
  Typography,
  Box,
} from "@mui/material";

import { useParams } from "react-router-dom";
import react_blog from "../assets/images/react-blog.webp";
import mern_blog from "../assets/images/mern-blog-image.webp";
import mui_blog from "../assets/images/mui-blog-image.webp";

const blogs = [
  {
    id: 1,
    title: "Getting Started with React",
    content:
      "React is a JavaScript library for building user interfaces. It uses components and virtual DOM for efficient rendering.",
    image: react_blog,
  },
  {
    id: 2,
    title: "Understanding MERN Stack",
    content:
      "The MERN stack combines MongoDB, Express.js, React, and Node.js to build full-stack web applications.",
    image: mern_blog,
  },
  {
    id: 3,
    title: "Why Material UI is Great",
    content:
      "Material UI provides pre-built React components following Google's Material Design principles.",
    image:mui_blog,
  },
];

export default function BlogDetails() {
  const { id } = useParams();

  const blog = blogs.find(
    (blog) => blog.id === Number(id)
  );

  if (!blog) {
    return (
      <Typography variant="h4">
        Blog not found
      </Typography>
    );
  }

  return (
    <Container maxWidth="md" sx={{ py: 5 }}>
      <Typography
        variant="h3"
        gutterBottom
      >
        {blog.title}
      </Typography>

      <Box
        component="img"
        src={blog.image}
        alt={blog.title}
        sx={{
          width: "100%",
          borderRadius: 2,
          mb: 4,
        }}
      />

      <Typography
        variant="body1"
        sx={{
          fontSize: "1.1rem",
          lineHeight: 2,
        }}
      >
        {blog.content}
      </Typography>
    </Container>
  );
}
